namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeSubmission
{
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
}

using RecipeCommunity.Models;

namespace RecipeCommunity.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, Tomato sauce, Fresh mozzarella, Basil, Olive oil", Steps = "1. Preheat oven to 475°F\n2. Roll out dough\n3. Spread sauce\n4. Add mozzarella\n5. Bake 10-12 minutes\n6. Top with fresh basil", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook pasta al dente\n2. Crisp guanciale\n3. Mix eggs with cheese\n4. Toss hot pasta with guanciale\n5. Add egg mixture off heat\n6. Season with pepper", AverageRating = 4.8, RatingCount = 8 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato puree, Cream, Onion, Garlic, Ginger", Steps = "1. Marinate chicken in spiced yogurt\n2. Grill or bake chicken\n3. Sauté onions, garlic, ginger\n4. Add tomato puree and spices\n5. Simmer with cream\n6. Add chicken pieces", AverageRating = 4.7, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Pad Thai", Category = "Thai", Ingredients = "Rice noodles, Shrimp, Tofu, Bean sprouts, Peanuts, Tamarind paste, Fish sauce, Lime", Steps = "1. Soak noodles\n2. Make tamarind sauce\n3. Stir-fry shrimp and tofu\n4. Add noodles and sauce\n5. Toss with bean sprouts\n6. Garnish with peanuts and lime", AverageRating = 4.3, RatingCount = 10 },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco shells, Lettuce, Tomato, Cheddar cheese, Sour cream, Cumin, Chili powder", Steps = "1. Season and brown beef\n2. Warm taco shells\n3. Dice vegetables\n4. Assemble tacos with toppings\n5. Serve with sour cream", AverageRating = 4.1, RatingCount = 20 },
        new Recipe { Id = 6, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Cilantro, Red onion, Jalapeño, Tomato, Salt", Steps = "1. Mash avocados\n2. Add lime juice\n3. Fold in diced onion, tomato, jalapeño\n4. Add cilantro\n5. Season with salt", AverageRating = 4.6, RatingCount = 18 },
        new Recipe { Id = 7, Title = "Green Curry", Category = "Thai", Ingredients = "Green curry paste, Coconut milk, Chicken, Thai basil, Bamboo shoots, Fish sauce, Sugar", Steps = "1. Fry curry paste in coconut cream\n2. Add chicken slices\n3. Pour in coconut milk\n4. Add bamboo shoots\n5. Season with fish sauce and sugar\n6. Finish with Thai basil", AverageRating = 4.4, RatingCount = 7 },
        new Recipe { Id = 8, Title = "Butter Chicken", Category = "Indian", Ingredients = "Chicken, Butter, Tomato puree, Cream, Fenugreek leaves, Garam masala, Ginger, Garlic", Steps = "1. Marinate and grill chicken\n2. Make tomato-butter sauce\n3. Add spices and cream\n4. Simmer chicken in sauce\n5. Finish with fenugreek leaves", AverageRating = 4.9, RatingCount = 22 },
    };

    public List<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
        }
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

