@rendermode InteractiveServer

<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "") @(star <= _hoverRating ? "hover" : "")"
              @onclick="() => SubmitRating(star)"
              @onmouseover="() => _hoverRating = star"
              @onmouseout="() => _hoverRating = 0">
            ★
        </span>
    }
    <span class="rating-info">(@AverageRating.ToString("F1") avg, @RatingCount ratings)</span>
</div>

@if (_submitted)
{
    <div class="rating-thanks">Thanks for rating!</div>
}

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double AverageRating { get; set; }
    [Parameter] public int RatingCount { get; set; }
    [Parameter] public EventCallback<int> OnRated { get; set; }

    private int _selectedRating;
    private int _hoverRating;
    private bool _submitted;

    private async Task SubmitRating(int stars)
    {
        _selectedRating = stars;
        _submitted = true;
        await OnRated.InvokeAsync(stars);
    }
}

