@page "/"
@using RecipeCommunity.Services

<PageTitle>Recipe Community</PageTitle>

<div class="hero">
    <h1>🍳 Recipe Community</h1>
    <p class="lead">Discover and share delicious recipes from around the world</p>
</div>

<h2>Browse by Category</h2>
<div class="category-grid">
    @foreach (var category in _categories)
    {
        <a href="/recipes/@category.ToLower()" class="category-card">
            <span class="category-icon">@GetCategoryIcon(category)</span>
            <h3>@category</h3>
            <p>@RecipeService.GetRecipesByCategory(category).Count recipes</p>
        </a>
    }
</div>

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private List<string> _categories = new();

    protected override void OnInitialized()
    {
        _categories = RecipeService.GetCategories();
    }

    private string GetCategoryIcon(string category) => category switch
    {
        "Italian" => "🍝",
        "Indian" => "🍛",
        "Thai" => "🥘",
        "Mexican" => "🌮",
        _ => "🍽️"
    };
}

