@page "/recipes/{Category}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>@Category Recipes - Recipe Community</PageTitle>

<nav aria-label="breadcrumb">
    <a href="/">Home</a> &rsaquo; <span>@Category</span>
</nav>

<h1>@Category Recipes</h1>

@if (_recipes.Any())
{
    <div class="recipe-list">
        @foreach (var recipe in _recipes)
        {
            <a href="/recipe/@recipe.Id" class="recipe-card">
                <h3>@recipe.Title</h3>
                <div class="recipe-meta">
                    <span class="stars">@GetStars(recipe.AverageRating)</span>
                    <span>(@recipe.AverageRating.ToString("F1")) · @recipe.RatingCount ratings</span>
                </div>
            </a>
        }
    </div>
}
else
{
    <p>No recipes found in this category.</p>
}

@code {
    [Parameter] public string Category { get; set; } = string.Empty;
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private List<Recipe> _recipes = new();

    protected override void OnInitialized()
    {
        _recipes = RecipeService.GetRecipesByCategory(Category);
    }

    private string GetStars(double rating)
    {
        var full = (int)Math.Round(rating);
        return new string('★', full) + new string('☆', 5 - full);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Services
@using RecipeCommunity.Models
@using RecipeCommunity.Components.Shared

<PageTitle>@(_recipe?.Title ?? "Recipe") - Recipe Community</PageTitle>

@if (_recipe is not null)
{
    <nav aria-label="breadcrumb">
        <a href="/">Home</a> &rsaquo; <a href="/recipes/@_recipe.Category.ToLower()">@_recipe.Category</a> &rsaquo; <span>@_recipe.Title</span>
    </nav>

    <article class="recipe-detail">
        <h1>@_recipe.Title</h1>

        <StarRating RecipeId="@_recipe.Id"
                    AverageRating="@_recipe.AverageRating"
                    RatingCount="@_recipe.RatingCount"
                    OnRated="HandleRating" />

        <section class="ingredients">
            <h2>Ingredients</h2>
            <ul>
                @foreach (var ingredient in _recipe.Ingredients.Split(',', StringSplitOptions.TrimEntries))
                {
                    <li>@ingredient</li>
                }
            </ul>
        </section>

        <section class="steps">
            <h2>Instructions</h2>
            @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p>@step</p>
            }
        </section>
    </article>
}
else
{
    <p>Recipe not found.</p>
}

@code {
    [Parameter] public int Id { get; set; }
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private Recipe? _recipe;

    protected override void OnInitialized()
    {
        _recipe = RecipeService.GetRecipeById(Id);
    }

    private void HandleRating(int stars)
    {
        RecipeService.AddRating(Id, stars);
        _recipe = RecipeService.GetRecipeById(Id);
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Services
@using RecipeCommunity.Models

<PageTitle>Submit a Recipe - Recipe Community</PageTitle>

<h1>Submit a Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (_submitted)
{
    <div class="success-message">
        <h2>✅ Recipe Submitted!</h2>
        <p>Thank you for sharing "<strong>@_model.Title</strong>" with the community.</p>
        <a href="/">Back to Home</a>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" class="recipe-form">
        <DataAnnotationsValidator />

        <div class="form-group">
            <label for="title">Recipe Title</label>
            <InputText id="title" @bind-Value="_model.Title" placeholder="e.g., Grandma's Apple Pie" />
        </div>

        <div class="form-group">
            <label for="category">Category</label>
            <InputSelect id="category" @bind-Value="_model.Category">
                <option value="">-- Select a category --</option>
                <option value="Italian">Italian</option>
                <option value="Indian">Indian</option>
                <option value="Thai">Thai</option>
                <option value="Mexican">Mexican</option>
                <option value="American">American</option>
                <option value="French">French</option>
                <option value="Japanese">Japanese</option>
                <option value="Other">Other</option>
            </InputSelect>
        </div>

        <div class="form-group">
            <label for="ingredients">Ingredients (comma-separated)</label>
            <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" rows="4"
                           placeholder="e.g., 2 cups flour, 1 cup sugar, 3 apples..." />
        </div>

        <div class="form-group">
            <label for="steps">Steps (one per line)</label>
            <InputTextArea id="steps" @bind-Value="_model.Steps" rows="6"
                           placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;3. ..." />
        </div>

        <button type="submit" class="btn-submit"
                disabled="@(string.IsNullOrWhiteSpace(_model.Title) || string.IsNullOrWhiteSpace(_model.Category))">
            Submit Recipe
        </button>
    </EditForm>
}

@code {
    [Inject] private RecipeService RecipeService { get; set; } = default!;

    private RecipeSubmission _model = new();
    private bool _submitted;

    private void HandleSubmit()
    {
        RecipeService.SubmitRecipe(_model);
        _submitted = true;
    }
}

